import {attachAmap} from '../public/map.mjs';
import {distanceKm,withinRadius,moveStop,csvText,toWgs84,validateStops} from '../src/domain/route.mjs';
const $=s=>document.querySelector(s), data=window.MUSEUM_DATA, venues=data.venues, center=venues[0], storageKey='museum-route-design-v01';
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=id=>`<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;
let state={tab:'discover',query:'',filter:'all',city:'苏州市',grade:'',radius:100,stops:[venues[0],venues[2],venues[3]].map(v=>({id:v.id,day:1,minutes:120})),favorites:[venues[4].id],results:[],date:'2026-10-24',mode:'尚未决定'};
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved){validateStops(saved.stops);if(saved.stops.every(x=>venues.some(v=>v.id===x.id)))state={...state,...saved,tab:'discover',query:'',filter:'all',city:'苏州市'};}}catch{}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('浏览器存储不可用，本次更改仅在当前页面保留');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
let map,markers,routeLine,tileErrors=0;
function initMap(){
 if(!window.L){$('#map').innerHTML='<div class="empty">地图组件未加载，仍可使用列表。</div>';return;}
 const p=center;map=L.map('map',{zoomControl:true,scrollWheelZoom:false}).setView([p.latitude,p.longitude],10);markers=L.layerGroup().addTo(map);
 attachAmap(map,L,{onError:message=>{if(message)toast(message);}});
 L.control.scale({imperial:false}).addTo(map);
 const circle=L.circle([p.latitude,p.longitude],{radius:state.radius*1000,color:'#6a8870',weight:1,dashArray:'5 7',fillOpacity:.02}).addTo(map);
 map.radiusCircle=circle;
}
const rows=()=>state.stops.map(s=>({...venues.find(v=>v.id===s.id),...s}));
function filteredVenues(){return withinRadius(venues,center,state.radius).located.filter(v=>(!state.query||[v.name,v.intro,...v.themes,v.district].join(' ').includes(state.query))&&(!state.grade||v.grade===state.grade)&&(state.filter!=='county'||v.county)&&(state.filter!=='theme'||v.label==='特色专题'||v.themes.includes('砖瓦工艺')));}
function card(v){const selected=state.stops.some(s=>s.id===v.id);return `<article class="museum-card ${selected?'selected':''}"><div class="card-top"><span class="category ${v.county?'county':''}">${escape(v.label)}</span><span class="distance">${distanceKm(center,v).toFixed(1)} km · 直线</span></div><h3><button class="card-detail" data-detail="${escape(v.id)}">${escape(v.name)}</button></h3><p>${escape(v.intro||'此馆的特色介绍尚待核实，可交给 Agent 补充。')}</p><div class="card-tags">${v.themes.map(t=>`<span class="tag">${escape(t)}</span>`).join('')}<span class="tag pending">开放待核实</span></div><div class="card-actions"><button class="outline" data-add="${escape(v.id)}">${selected?'✓ 已在路线':'+ 加入路线'}</button><button class="quiet" aria-label="${state.favorites.includes(v.id)?'取消收藏':'收藏'}${escape(v.name)}" data-favorite="${escape(v.id)}">${state.favorites.includes(v.id)?'♥':'♡'}</button><span class="grade-note">${v.grade?escape(v.grade)+' · '+escape(v.gradeAsOf)+'年':'等级待核实'}</span></div></article>`;}
function renderDiscovery(){
 if(state.city==='全国'){
  const matches=data.catalog.filter(v=>(!state.query||[v.name,v.province,v.city_candidate].join(' ').includes(state.query))&&(!state.grade||v.grade===state.grade)&&(state.filter!=='county'||v.county_level_candidate==='true')&&(state.filter!=='theme'||/艺术|陶瓷|砖瓦|青铜|钱币|丝绸/.test(v.name)));
  $('#list-heading').textContent='全国历史名录';$('#result-count').textContent=matches.length+' 条';$('#scope-note').textContent='尚未全量定位 · 不应用100km半径';
  $('#museum-list').innerHTML=matches.slice(0,40).map(v=>`<article class="museum-card"><span class="category">${escape(v.province)} · ${v.county_level_candidate==='true'?'县域候选':'基础名录'}</span><h3>${escape(v.name)}</h3><div class="card-tags"><span class="tag">${escape(v.grade)} · 2019年</span><span class="tag pending">地址与坐标待补</span></div><button class="outline" data-verify-name="${escape(v.name)}">请 Agent 核实与定位 ↗</button></article>`).join('')+(matches.length>40?'<p class="micro">先展示40条；请用关键词缩小范围。正式版提供分页。</p>':'');
  if(!matches.length)$('#museum-list').innerHTML='<div class="empty">没有匹配馆。可放宽条件，或交给 Agent 查找名录之外的新馆。</div>';
  $('.map-heading span').innerHTML='<i class="legend-dot"></i> 苏州试点 · 非全国定位';renderMap([]);return;
 }
 const filtered=filteredVenues();$('#list-heading').textContent='从这里开始';$('#result-count').textContent=filtered.length+' 处馆址';$('#scope-note').textContent='以苏州博物馆本馆为中心 · 直线距离';$('.map-heading span').innerHTML='<i class="legend-dot"></i> 目的地与周边';$('#museum-list').innerHTML=filtered.map(card).join('')||'<div class="empty">当前条件没有结果，试试更大的半径或其他分类。</div>';renderMap(filtered);
}
function renderMap(list){if(!map)return;markers.clearLayers();map.radiusCircle.setRadius(state.radius*1000);list.forEach(v=>{const p=v,i=state.stops.findIndex(s=>s.id===v.id),label=i>=0?i+1:'·';const m=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'',html:`<div class="pin ${v.county?'small-museum':''}">${label}</div>`,iconSize:[30,30],iconAnchor:[15,15]}),title:v.name}).addTo(markers);m.bindTooltip(escape(v.name),{direction:'top'});m.on('click',()=>showDetail(v.id));});if(routeLine)map.removeLayer(routeLine);const coords=rows().map(v=>[v.latitude,v.longitude]);if(coords.length>1)routeLine=L.polyline(coords,{color:'#b65332',weight:2,dashArray:'5 7',opacity:.7}).addTo(map);}
function showTab(tab){state.tab=tab;for(const p of document.querySelectorAll('.page'))p.hidden=p.id!==tab+'-page';for(const b of document.querySelectorAll('[data-tab]'))b.classList.toggle('active',b.dataset.tab===tab);$('#page-title').innerHTML=tab==='discover'?'苏州，馆里见<span>。</span>':({route:'把喜欢的馆，串起来',favorites:'留一份好奇，给下一次',results:'走过之后，也有回响',data:'每一条信息，都有来处'}[tab]);if(tab==='discover'){renderDiscovery();requestAnimationFrame(()=>map?.invalidateSize());}if(tab==='route')renderRoute();if(tab==='favorites')renderFavorites();if(tab==='results')renderResults();}
function renderRoute(){const rr=rows();$('#route-list').innerHTML=rr.map((v,i)=>`<article class="route-row"><span class="stop-number">${i+1}</span><div class="route-main"><h3><button class="card-detail" data-detail="${escape(v.id)}">${escape(v.name)}</button></h3><p>${escape(v.district)} · 开放和预约待复核</p><div class="route-options"><label>第 <select data-day="${escape(v.id)}">${[1,2,3,4,5].map(d=>`<option value="${d}" ${d===v.day?'selected':''}>${d}</option>`).join('')}</select> 天</label><label>参观 <input type="number" min="15" max="600" step="15" value="${v.minutes}" data-minutes="${escape(v.id)}"> 分钟</label></div></div><div class="stop-controls"><button class="quiet" data-move="${escape(v.id)}" data-delta="-1" aria-label="上移${escape(v.name)}" ${i===0?'disabled':''}>↑</button><button class="quiet" data-move="${escape(v.id)}" data-delta="1" aria-label="下移${escape(v.name)}" ${i===rr.length-1?'disabled':''}>↓</button><button class="quiet" data-remove="${escape(v.id)}" aria-label="移除${escape(v.name)}">×</button></div></article>`).join('')||'<div class="empty">从发现页面加入第一座馆，路线会从这里开始。</div>';let km=0;for(let i=1;i<rr.length;i++)if(rr[i].day===rr[i-1].day)km+=distanceKm(rr[i-1],rr[i]);$('#distance-total').textContent=`${rr.length} 处馆址 · 同日相邻点直线合计 ${km.toFixed(1)} km（非路程）`;$('#trip-date').value=state.date;$('#trip-mode').value=state.mode;}
function renderFavorites(){$('#favorites-list').innerHTML=venues.filter(v=>state.favorites.includes(v.id)).map(card).join('')||'<div class="empty">点一下馆旁边的收藏，把兴趣留在这里。</div>';}
function renderResults(){$('#results-list').innerHTML=state.results.map(v=>`<article class="museum-card"><span class="category">${escape(v.type)} · ${escape(v.at)}</span><h3>${escape(v.title)}</h3><p>${escape(v.note)}</p></article>`).join('')||'<div class="empty">导出路线或准备 Agent 核实清单后，这里会显示本浏览器的操作记录。</div>';}
function addStop(id){if(!state.stops.some(s=>s.id===id)){state.stops.push({id,day:1,minutes:120});persist();refresh();toast('已加入路线，可调整顺序与参观时长');}else toast('这处馆址已在路线中');}
function refresh(){$('#route-count').textContent=state.stops.length;renderDiscovery();if(state.tab==='route')renderRoute();if(state.tab==='favorites')renderFavorites();if(state.tab==='results')renderResults();}
function showDetail(id){const v=venues.find(v=>v.id===id);if(!v)return;$('#detail-content').innerHTML=`<div class="dialog-head"><div><p class="eyebrow">${escape(v.label)} · ${escape(v.district)}</p><h2>${escape(v.name)}</h2></div><button class="quiet" data-close="detail">关闭 ×</button></div><div class="detail-section"><h3>为什么值得留意</h3><p>${escape(v.intro||'特色介绍待核实。')}</p>${v.featuredExhibits?`<p>${escape(v.featuredExhibits)}</p>`:''}<a href="${escape(v.introSource||v.officialUrl)}" target="_blank" rel="noopener noreferrer">查看介绍来源 ↗</a></div><div class="detail-section"><h3>位置与距离</h3><p>${escape(v.address)}<br>${v.longitude}, ${v.latitude} · ${v.crs}<br>距中心 ${distanceKm(center,v).toFixed(1)} km（直线）</p><a href="${escape(v.sourceUrl)}" target="_blank" rel="noopener noreferrer">在高德打开点位 ↗</a></div><div class="detail-section"><h3>常规开放时间 · 来自高德POI</h3><p>${escape(v.openingHours)}</p><p class="soft-note">尚未核实 ${escape(state.date)} 当天的临时公告、预约与展品在展情况。</p><small>采集日 ${escape(v.checkedAt)}；采集日不等于公告有效日。</small></div><div class="detail-section"><h3>官网与公众号</h3><a href="${escape(v.officialUrl)}" target="_blank" rel="noopener noreferrer">官方/主管部门页面 ↗</a><p>公众号账号与介绍：尚待核实，未用推测值补齐。</p></div><div class="card-actions"><button class="primary" data-add="${escape(v.id)}">加入路线</button><button class="outline" data-verify="${escape(v.id)}">请 Agent 核实</button></div>`;$('#detail').showModal();}
function prompt(extra=''){return ['请帮助我完善博物馆参观路线。','当前城市：'+state.city,'日期：'+state.date+'；交通：'+state.mode,'以下顺序由用户手动安排，优化前请先给建议，不直接覆盖。',...rows().map((v,i)=>`${i+1}. 第${v.day}天 ${v.name}；${v.address}；坐标${v.longitude},${v.latitude}（${v.crs}）；馆址ID：${v.id}；机构ID：${v.museumId}；计划参观${v.minutes}分钟（规划值）；来源：${v.sourceUrl}`),'任务：核实出行当天常规时间、临时闭馆/展厅关闭、预约和最后入馆；确认特色展品是否在展；根据实际交通工具查询路段，补充每日路书和备选小馆。','全国名录是2019历史基础快照，不作为当前评级或开放证明。100km为直线半径，不是车程。','每个结论附来源URL、发布时间/有效期和检索日。未查到标未知；公众号不可访问不编内容。','将更新作为带museum/venue ID、输入revision和来源的字段候选；待用户确认后回存工作台。',extra].filter(Boolean).join('\n');}
function openPrompt(extra){$('#detail').close();$('#prompt-text').value=prompt(extra);$('#prompt-dialog').showModal();state.results.unshift({type:'准备核实',at:new Date().toLocaleString('zh-CN'),title:'路线核实提示词',note:'已生成预览；尚未发送给 DSH Agent。'});state.results=state.results.slice(0,30);persist();}
function exportRoute(format){const rr=rows();if(!rr.length){toast('先加入至少一处馆址');return;}let text,mime;if(format==='json'){text=JSON.stringify({schemaVersion:1,date:state.date,mode:state.mode,stops:rr,reviewState:'draft'},null,2);mime='application/json';}else if(format==='csv'){text=csvText(rr);mime='text/csv;charset=utf-8';}else{text=['# 苏州寻馆路线草案','',`日期：${state.date}；交通：${state.mode}`,'','> 所有开放状态待按出行日期复核，连线和直线距离不代表道路导航。','',...rr.flatMap((v,i)=>[`## ${i+1}. 第${v.day}天 · ${v.name}`,`- 地址：${v.address}`,`- 坐标：${v.longitude},${v.latitude}（${v.crs}）`,`- 计划参观：${v.minutes}分钟（用户规划值）`,`- 常规时间（高德POI）：${v.openingHours}`,`- 开放状态：出行当天待核实`,`- 介绍来源：${v.introSource||v.officialUrl}`,`- 点位来源：${v.sourceUrl}`,''])].join('\n');mime='text/markdown;charset=utf-8';}const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=`museum-route-${state.date}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state.results.unshift({type:'导出请求',at:new Date().toLocaleString('zh-CN'),title:`${format.toUpperCase()} 路线 · ${rr.length}馆`,note:'浏览器已发起下载，请在下载目录查看；此条记录不是文件系统保存证明。'});state.results=state.results.slice(0,30);persist();toast('已发起下载，路线顺序与当前列表一致');}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.tab)showTab(d.tab);if(d.go)showTab(d.go);if(d.filter){state.filter=d.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===el));renderDiscovery();}if(d.add)addStop(d.add);if(d.detail)showDetail(d.detail);if(d.favorite){state.favorites=state.favorites.includes(d.favorite)?state.favorites.filter(x=>x!==d.favorite):[...state.favorites,d.favorite];persist();refresh();}if(d.move){state.stops=moveStop(state.stops,d.move,Number(d.delta));persist();refresh();}if(d.remove){state.stops=state.stops.filter(x=>x.id!==d.remove);persist();refresh();}if(d.close)document.getElementById(d.close).close();if(d.verify)openPrompt('重点核实：'+venues.find(v=>v.id===d.verify)?.name);if(d.verifyName)openPrompt('另外请核实并地理匹配：'+d.verifyName+'。该馆来自2019年名录，目前地址/坐标缺失，不应假设在苏州。');if(d.export)exportRoute(d.export);});
$('#query').addEventListener('input',e=>{state.query=e.target.value.trim();renderDiscovery();});$('#search-button').onclick=()=>renderDiscovery();$('#city').onchange=e=>{state.city=e.target.value;renderDiscovery();};$('#grade').onchange=e=>{state.grade=e.target.value;renderDiscovery();};$('#radius').onchange=e=>{state.radius=Number(e.target.value);renderDiscovery();};$('#fit-map').onclick=()=>{if(!map)return;const ps=filteredVenues();if(ps.length)map.fitBounds(ps.map(p=>[p.latitude,p.longitude]),{padding:[30,30],maxZoom:12});};$('#about-data').onclick=()=>showTab('data');$('#large-font').onclick=()=>{document.body.classList.toggle('large');$('#large-font').textContent=document.body.classList.contains('large')?'标准字':'大字';map?.invalidateSize();};$('#agent-route').onclick=()=>openPrompt();$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText($('#prompt-text').value);toast('已复制。当前尚未发送或连接原生会话。');}catch{$('#prompt-text').select();toast('请使用复制快捷键复制已选文字');}};
$('#route-list').addEventListener('change',e=>{const id=e.target.dataset.day||e.target.dataset.minutes,s=state.stops.find(x=>x.id===id);if(!s)return;const old={...s};if(e.target.dataset.day)s.day=Number(e.target.value);else s.minutes=Number(e.target.value);try{validateStops(state.stops);persist();renderRoute();}catch{Object.assign(s,old);renderRoute();toast('请输入15到600之间的整数分钟数');}});
$('#trip-date').onchange=e=>{state.date=e.target.value;persist();};$('#trip-mode').onchange=e=>{state.mode=e.target.value;persist();};
initMap();refresh();if(map)$('#fit-map').click();
